from itertools import product

def corr(s, k):
    return sum(s[i]*s[i+k] for i in range(len(s)-k))

results = []
for bits in product([-1,1], repeat=13):
    s = list(bits)
    if s[8]!=1 or s[10]!=-1: continue
    if corr(s,4)!=2: continue
    if corr(s,5)!=-1: continue
    ss = sum(corr(s,k)**2 for k in range(1,13))
    if ss <= 28:
        results.append((ss, s))
        if len(results) < 5:
            print(ss, s)
print("total:", len(results))
